import random
import struct

# Generator for LZMA properties blob (5 bytes):
# - byte0 encodes lc/lp/pb with: 0 <= lc <= 8, 0 <= lp <= 4, 0 <= pb <= 4 and (lc + lp) <= 8
#   encoding: props0 = (pb * 45) + (lp * 9) + lc
# - bytes1..4 are little-endian dictionary size. Typical valid sizes are powers of two or
#   multiples of 1 << 20. The SDK clamps to min (1<<12) and platform-dependent max.
# We also occasionally emit sizes different from 5 to exercise stubs that mod size to [1..16],
# but we always place a valid 5-byte properties at the start so functions that use size==5 succeed.

_VALID_DICT_POW2 = [1 << n for n in range(12, 30)]  # 4 KiB .. 512 MiB
# Some other valid, interesting dictionary sizes (SDK often rounds):
_VALID_DICT_MISC = [
    0,                 # request default (some APIs accept 0 -> default). For props blob, 0 is valid LE value; decoder interprets as 0 => treated as at least 1<<12
    (1 << 20) - 1,     # non power-of-two, boundary below 1 MiB
    (1 << 20) + 12345, # odd size
    3 * (1 << 20),     # 3 MiB
    (1 << 24),         # 16 MiB typical default in many builds (1<<24)
    (1 << 27),         # upper 32-bit build guideline
    (3 << 29)          # large (1.5 GiB) for 64-bit builds
]


def _encode_props_byte(lc: int, lp: int, pb: int) -> int:
    return pb * 45 + lp * 9 + lc


def _random_lc_lp_pb(rng: random.Random):
    # Choose combinations that satisfy lc+lp <= 8
    choices = []
    for lc in range(0, 9):
        for lp in range(0, 5):
            if lc + lp <= 8:
                for pb in range(0, 5):
                    choices.append((lc, lp, pb))
    return rng.choice(choices)


def _random_dict_size(rng: random.Random) -> int:
    bucket = rng.randrange(0, 4)
    if bucket == 0:
        return rng.choice(_VALID_DICT_POW2)
    elif bucket == 1:
        # power of two scaled by a small factor
        base = rng.choice(_VALID_DICT_POW2)
        mult = rng.choice([1, 3, 5, 7])
        val = base * mult
        # cap reasonably to avoid overflow in some decoders
        return min(val, (3 << 29))
    elif bucket == 2:
        return rng.choice(_VALID_DICT_MISC)
    else:
        # arbitrary but within a broad, sane range
        return rng.randrange(1 << 12, (3 << 29) + 1)


def _make_valid_props(rng: random.Random) -> bytes:
    lc, lp, pb = _random_lc_lp_pb(rng)
    props0 = _encode_props_byte(lc, lp, pb)
    dict_size = _random_dict_size(rng)
    return bytes([props0]) + struct.pack('<I', dict_size & 0xFFFFFFFF)


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Always start buffer with a valid 5-byte properties blob so calls with size==5 succeed.
    props = _make_valid_props(rng)

    # Some stubs size the input as (len % 16) with 0 -> 5. To provide variability for those paths,
    # append additional bytes so different modulo values occur across seeds, while keeping the total
    # under 4096 bytes.
    # We'll append a small sequence of additional, independent props blobs and a few padding bytes.
    tail = bytearray()

    # Append 0..3 extra valid props blobs
    extra_count = rng.randrange(0, 4)
    for _ in range(extra_count):
        tail += _make_valid_props(rng)

    # Add a small padding run of random bytes (still harmless for property consumers that ignore them)
    pad_len = rng.randrange(0, 11)  # up to 10 bytes
    if pad_len:
        tail += rng.randbytes(pad_len)

    buf = props + bytes(tail)
    # Ensure maximum size constraint
    if len(buf) > 4096:
        buf = buf[:4096]
    return buf
